fn solve(n: i8, k: i8) -> Vec<i8> {
    // Number of unselected items
    let unselected = n - k;

    if k == 0 || k == n {
        // If selected count is 0 or equals total count, both min and max are 0
        vec![0, 0]
    } else {
        // Otherwise, min is 1, max is the smaller of unselected and 2 * selected
        let x_min = 1;
        let x_max = unselected.min(2 * k);
        vec![x_min, x_max]
    }
}